{
  "headline": "FDA's records trace our epinephrine supply to plants with OAI classifications and Warning Letters within three years before the shortage posting",
  "headline_cites": ["E16", "E26", "E38", "E42", "E50", "E74", "E17", "E23", "E32", "E34", "E37", "E56", "E57", "E62", "E65", "E72", "D10", "D13", "D15", "D16", "D17", "D20", "D21", "D22", "D23"],
  "sentences": [
    {
      "text": "Our epinephrine products at Corvale East and Corvale General are labeled with plants that have received FDA Official Action Indicated (OAI) classifications and Warning Letters.",
      "cites": ["E16", "E26", "E38", "E42", "E50", "E74"]
    },
    {
      "text": "The Boehringer Ingelheim Pharma GmbH & Co. KG plant (FEI 3002806556) on the Amneal label received an OAI classification from inspection 808119 ending 2012-11-12 and a Warning Letter on 2013-05-06.",
      "cites": ["E17", "E23", "E26"]
    },
    {
      "text": "The Hospira, Inc. plant (FEI 1925262) on the Amneal label received OAI classifications from inspections 976095 ending 2016-06-08 and 1064827 ending 2018-08-15, and a Warning Letter on 2017-02-14.",
      "cites": ["E32", "E34", "E37", "E38"]
    },
    {
      "text": "The Fresenius Kabi USA, LLC plant (FEI 3001833549) on the Fresenius Kabi label received OAI classifications from inspections 732653 ending 2011-07-08 and 815426 ending 2013-01-11, and a Warning Letter on 2012-02-22.",
      "cites": ["E62", "E65", "E72", "E50"]
    },
    {
      "text": "The Fresenius Kabi USA LLC plant (FEI 1450022) received OAI classifications from inspections 1123748 ending 2020-05-18 and 1174894 ending 2022-06-30.",
      "cites": ["E56", "E57", "E50"]
    },
    {
      "text": "FDA first posted the epinephrine shortage on 2012-02-22 citing manufacturing delay, and as of 2026-10-21 the shortage has been on FDA's list for 176 months.",
      "cites": ["E86", "D27"]
    },
    {
      "text": "The rule-based transfer option moves 25 units from Corvale East (15 days on hand) to Corvale Lakeside (7.4 days on hand), bringing Lakeside to 14 days while East retains two weeks of supply.",
      "cites": ["D1", "D3", "D24"]
    }
  ]
}
